/bin/bash -lc "python - <<'PY'
import inspect
import bioblend.galaxy.histories as h
print(dir(h))
for n in dir(h):
    if 'History' in n:
        c=getattr(h,n)
        print(n,c)
        if inspect.isclass(c):
            print([x for x in dir(c) if not x.startswith('_')])
            for m in ['copy_history','create_history','show_history']:
                if hasattr(c,m): print(m, inspect.signature(getattr(c,m)))
PY"

